<script lang="ts">
 import { onMount } from 'svelte';
 import { Hexagon, LayoutDashboard, ChartCandlestick, Bot, FlaskConical, Database, Settings2, ChevronDown, ArrowUpRight, ArrowDownRight, Search, Bell, Menu, X, ShieldCheck, Radio, Pause, Play, Download, Plus, ArrowRight, Activity, CircleHelp, SlidersHorizontal, Clock3, Wallet, Check, RefreshCw } from 'lucide-svelte';
 import MarketChart from '$lib/components/MarketChart.svelte';
 import CloudHive from '$lib/components/CloudHive.svelte';
 import BeeAvatar from '$lib/components/BeeAvatar.svelte';
 import {marketCatalog, beeCatalog, previewCandles, fetchCandles, fetchQuotes, loadPaper, placePaperOrder, closePaperPosition, savePaper, exportLedger} from '$lib/hive';
 let markets:any[]=$state([...marketCatalog]); let bees:any[]=$state([...beeCatalog]);let account:any=$state(null);let selected=$state('BTC-USDT');let timeframe=$state('15m');let candles:any[]=$state(previewCandles('BTC-USDT'));let source=$state('Preview dataset · synthetic · 15 Oct 2025');let live=$state(false);let loading=$state(true);let tab=$state('Activity');let marketFilter=$state('All markets');let query=$state('');let side=$state<'buy'|'sell'>('buy');let amount=$state('100');let modal=$state('');let notice=$state('');let busy=$state(false);let drawer=$state(false);let selectedBee=$state('');let updated=$state('—');let activeNav=$state('Overview');
 let market=$derived(markets.find(m=>m.symbol===selected)||markets[0]);let visibleMarkets=$derived(markets.filter(m=>(marketFilter==='All markets'||m.kind===marketFilter.toLowerCase())&&(m.symbol+' '+m.name).toLowerCase().includes(query.toLowerCase())));let close=$derived(candles.at(-1));
 const money=(n:any,d=2)=>typeof n==='number'?n.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
 let chartRequest=0; async function chart(){const request=++chartRequest;const symbol=selected;const bar=timeframe;loading=true;try{const data=await fetchCandles(symbol,bar);if(request!==chartRequest)return;candles=data.candles;source=data.source;live=data.live;updated=new Date(data.time).toLocaleTimeString('en-GB');}catch(e){if(request===chartRequest)notice=String(e);}finally{if(request===chartRequest)loading=false;}}
 async function quotes(){try{markets=await fetchQuotes();}catch{notice='Public quotes unavailable. Paper execution requires a fresh quote.';}}
 onMount(()=>{account=loadPaper();chart();quotes();const timer=setInterval(()=>{quotes();chart();},60000);return()=>clearInterval(timer);});
 async function selectMarket(symbol:string){selected=symbol;await chart();}
 async function order(){busy=true;notice='';try{account=await placePaperOrder(account,{symbol:selected,side,amount:Number(amount),beeId:selectedBee||undefined});notice='Paper order recorded. Your ledger has been updated.';}catch(e){notice=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function closePosition(id:string){busy=true;try{account=await closePaperPosition(account,id);notice='Paper position closed.';}catch(e){notice=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 function toggle(){account={...account,paused:!account.paused};savePaper(account);notice=account.paused?'Paper execution paused. Market research continues.':'Paper execution enabled.';}
 function navigate(name:string){activeNav=name;drawer=false;if(name==='Hive')tab='Bees';if(name==='Research')tab='Model lab';if(name==='Data')tab='Data health';if(name==='Settings')modal='Workspace settings';if(name==='Markets')document.getElementById('market-watch')?.scrollIntoView({behavior:'smooth',block:'center'});if(['Hive','Research','Data'].includes(name))document.getElementById('workspace-tabs')?.scrollIntoView({behavior:'smooth',block:'center'});}
 function modalFocus(node:HTMLElement){const before=document.activeElement as HTMLElement;node.focus();function key(e:KeyboardEvent){if(e.key==='Escape')modal='';if(e.key==='Tab'){const nodes=Array.from(node.querySelectorAll<HTMLElement>('button,input,select,a[href]')).filter(el=>!el.hasAttribute('disabled'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===node)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}node.addEventListener('keydown',key);return{destroy(){node.removeEventListener('keydown',key);before?.focus();}};}
</script>

<svelte:head><title>OmieBot AI Trading · Market intelligence, working together</title><meta name="description" content="OmieBot AI Trading research and paper trading terminal. A transparent workspace for market data, specialist Bees and evaluated trading models."/></svelte:head>

