 <section id="workspace-tabs" class="activity-panel panel"><div class="activity-tabs">{#each ['Activity','Positions','Orders','Bees','Model lab','Cloud hive','Data health'] as t}<button class:chosen={tab===t} onclick={()=>tab=t}>{t}{#if t==='Positions'}<span>{account?.positions?.length??0}</span>{/if}</button>{/each}<button class="export-button" onclick={()=>account&&exportLedger(account)}><Download size={13}/> Export ledger</button></div><div class="table-scroll">{#if tab==='Activity'}<div class="table-header"><span>EVENT</span><span>MARKET</span><span>DETAIL</span><span>TIME</span></div>{#each account?.ledger??[] as entry}<div class="table-row"><span><Activity size={13}/> {entry.type||entry.action||'Paper fill'}</span><span>{entry.symbol||'—'}</span><span>{entry.side||''} ${money(entry.quantity*entry.price)}</span><span>{new Date(entry.timestamp??entry.time??Date.now()).toLocaleTimeString()}</span></div>{:else}<div class="table-empty"><Activity size={22}/><div><strong>Your research starts here</strong><p>Paper fills appear here with a browser-local ledger.</p></div><span class="tiny-badge">NO LIVE MONEY</span></div>{/each}{:else if tab==='Positions'}{#each account?.positions??[] as position}<div class="table-row"><span>{position.symbol}</span><span>{money(position.quantity??position.qty,6)} units</span><span>Entry ${money(position.entry)}</span><button class="outline-button" onclick={()=>closePosition(position.id)} disabled={busy}>Close paper position</button></div>{:else}<div class="table-empty"><Wallet size={22}/><div><strong>No open paper positions</strong><p>Place a simulated spot order to begin tracking a position.</p></div></div>{/each}{:else if tab==='Orders'}<div class="table-empty"><Check size={22}/><div><strong>Market orders settle immediately</strong><p>Completed paper fills are recorded in Activity. No pending orders.</p></div></div>{:else if tab==='Bees'}<div class="research-list">{#each bees as bee}<div><BeeAvatar color={bee.color} size={32}/><strong>{bee.name}</strong><span>{bee.description}</span><span class="tiny-badge">{bee.status}</span></div>{/each}</div>{:else if tab==='Model lab'}<div class="table-empty"><FlaskConical size={26}/><div><strong>Evidence before promotion</strong><p>Models progress through chronological backtests, cost stress tests and forward paper evaluation. No trained challenger is approved yet.</p></div><button class="outline-button" onclick={()=>modal='Model promotion'}>Review workflow <ArrowUpRight size={13}/></button></div>{:else if tab==='Cloud hive'}<CloudHive/>{:else}<div class="data-health"><div><span class="status-dot"></span><strong>{live?'Public candles received':'Preview candles active'}</strong><small>{source}</small></div><div><Database size={16}/><strong>{candles.length} candles</strong><small>Current chart window</small></div><div><ShieldCheck size={16}/><strong>Fresh quotes required</strong><small>Fail closed on execution</small></div></div>{/if}</div></section>
 <footer><div><span class="status-dot"></span> Local workspace ready <span>·</span> Paper workspace</div><span>Built for conviction. Designed for restraint.</span><button onclick={()=>modal='Workspace guide'}>Documentation <ArrowUpRight size={12}/></button></footer>
 </div>
</div>
